    private const string Technical="/api/v1/evaluations/technical-reviews";
    private sealed record TechnicalFixture(Guid Enrollment,Guid Player,Guid Group,Guid Plan,Guid Level,Guid Next,Guid[] Requirements,DateOnly Today);
    private async Task<TechnicalFixture> TechnicalSetup(HttpClient owner,HttpClient coach,FoundationDbContext db,Academy.Infrastructure.Structure.TrainingGroup? selected=null)
    {
        var options=await coach.GetFromJsonAsync<JsonElement>("/api/v1/evaluations/options");var sourceId=options.GetProperty("enrollments")[0].GetProperty("id").GetGuid();var source=await db.SportEnrollments.AsNoTracking().SingleAsync(e=>e.Id==sourceId);
        var guardian=await db.GuardianProfiles.Where(g=>g.AcademyId==source.AcademyId&&g.User.PhoneNumber==DemoSeed.GuardianPhone).Select(g=>g.Id).SingleAsync();var child=await FreshSkillChild(db,source,guardian);
        var parent=selected??await db.TrainingGroups.AsNoTracking().SingleAsync(g=>g.Id==source.TrainingGroupId);child.BranchId=parent.BranchId;child.SportId=parent.SportId;var group=Guid.NewGuid();var member=await db.AcademyMemberships.Where(m=>m.AcademyId==source.AcademyId&&m.Role==AcademyRole.Coach&&m.IsActive).Select(m=>m.Id).FirstAsync();
        db.TrainingGroups.Add(new(){Id=group,AcademyId=parent.AcademyId,ArabicName="مجموعة مراجعة فنية اصطناعية "+group.ToString("N")[..8],BranchId=parent.BranchId,SportId=parent.SportId,AgeCategoryId=parent.AgeCategoryId});db.StaffGroupAssignments.Add(new(){Id=Guid.NewGuid(),AcademyId=parent.AcademyId,TrainingGroupId=group,AcademyMembershipId=member});child.TrainingGroupId=group;await db.SaveChangesAsync();
        var(c,level,_)=await SkillDefinition(owner,child.SportId);await PublishSkills(owner,c);(await Send(owner,$"/api/v1/people/enrollments/{child.Id}/placement-level",new{levelId=level},true)).EnsureSuccessStatusCode();
        var p=await Send(owner,$"{Skills}/enrollments/{child.Id}/skill-plan",new SkillPlanWrite(c,Guid.NewGuid()));p.EnsureSuccessStatusCode();var plan=(await p.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();var req=await db.SkillRequirements.Where(r=>r.CurriculumId==c).OrderBy(r=>r.DisplayOrder).Select(r=>r.Id).ToArrayAsync();
        var next=await Send(owner,"/api/v1/manage/training-levels",new{sportId=child.SportId,arabicName="خطوة تالية اصطناعية "+group.ToString("N")[..8],rank=60});next.EnsureSuccessStatusCode();return new(child.Id,child.PlayerId,group,plan,level,(await next.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid(),req,await AttendanceCalendar.TodayAsync(source.AcademyId,db,TimeProvider.System));
    }
    private static string TechnicalPath(Guid plan)=>$"{Skills}/plans/{plan}/technical-reviews";
    private static async Task<JsonElement> TechnicalView(HttpClient c,Guid plan)=>await c.GetFromJsonAsync<JsonElement>(TechnicalPath(plan));
    private static TechnicalReviewWrite TechnicalBody(JsonElement d)=>new(d.GetProperty("plan").GetProperty("version").GetUInt32(),d.GetProperty("source").GetProperty("head").GetInt32(),d.GetProperty("latestRequestId").ValueKind==JsonValueKind.Null?null:d.GetProperty("latestRequestId").GetGuid(),Guid.NewGuid());
    private static async Task MasterAll(HttpClient c,TechnicalFixture f){foreach(var id in f.Requirements)(await Send(c,$"{Skills}/plans/{f.Plan}/reviews",new SkillReviewWrite(id,"Mastered",id==f.Requirements[0]?null:8,f.Today,"دليل فني اصطناعي محفوظ",Guid.NewGuid()))).EnsureSuccessStatusCode();}
    [Fact]public async Task Technical_request_requires_current_mastery_then_owner_decision_is_shared_without_level_group_or_money_changes()
    {
        using var owner=await Staff();using var coach=await Mobile(AcademyRole.Coach);using var family=await Mobile(AcademyRole.Guardian);using var foreign=await Staff(DemoSeed.FutureOwnerEmail);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var f=await TechnicalSetup(owner,coach,db);
        var initial=await TechnicalView(coach,f.Plan);Assert.False(initial.GetProperty("canRequest").GetBoolean());Assert.Equal(HttpStatusCode.Conflict,(await Send(coach,TechnicalPath(f.Plan),TechnicalBody(initial))).StatusCode);await MasterAll(coach,f);
        var before=await db.SportEnrollments.AsNoTracking().SingleAsync(e=>e.Id==f.Enrollment);var collections=await db.Collections.CountAsync();var subscriptions=await db.SubscriptionPeriods.CountAsync();var notices=await db.AcademyNotices.CountAsync();var report=await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28");
        var v=await TechnicalView(coach,f.Plan);Assert.True(v.GetProperty("canRequest").GetBoolean());var body=TechnicalBody(v);var response=await Send(coach,TechnicalPath(f.Plan),body);Assert.Equal(HttpStatusCode.Created,response.StatusCode);var id=(await response.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();Assert.Equal(id,(await(await Send(coach,TechnicalPath(f.Plan),body)).Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid());Assert.Equal(HttpStatusCode.Conflict,(await Send(coach,TechnicalPath(f.Plan),body with{SourceReviewSequence=999})).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Send(coach,TechnicalPath(f.Plan),body with{RequestId=Guid.NewGuid()})).StatusCode);
        Assert.False((await TechnicalView(coach,f.Plan)).GetProperty("canRequest").GetBoolean());var familyPath=$"/api/v1/guardian/children/{f.Player}/skills/plans/{f.Plan}/technical-reviews";var publicData=await family.GetFromJsonAsync<JsonElement>(familyPath);Assert.False(publicData.GetProperty("canRequest").GetBoolean());Assert.Equal(id,publicData.GetProperty("items")[0].GetProperty("request").GetProperty("id").GetGuid());
        var inbox=await owner.GetFromJsonAsync<JsonElement>(Technical+"/inbox");Assert.Contains(inbox.GetProperty("items").EnumerateArray(),x=>x.GetProperty("request").GetProperty("id").GetGuid()==id);Assert.Equal("لاعب رحلة مهارات اصطناعي",inbox.GetProperty("contexts").GetProperty(f.Enrollment.ToString()).GetProperty("player").GetString());Assert.Equal(HttpStatusCode.Forbidden,(await coach.GetAsync(Technical+"/inbox")).StatusCode);Assert.DoesNotContain(id.ToString(),await foreign.GetStringAsync(Technical+"/inbox"));
        Assert.Equal(HttpStatusCode.Forbidden,(await Send(family,TechnicalPath(f.Plan),body)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await family.GetAsync($"/api/v1/guardian/children/{Guid.NewGuid()}/skills/plans/{f.Plan}/technical-reviews")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await foreign.GetAsync($"{Technical}/{id}")).StatusCode);
        var detail=await owner.GetFromJsonAsync<JsonElement>($"{Technical}/{id}");Assert.Equal(2,detail.GetProperty("evidence").GetArrayLength());Assert.True(detail.GetProperty("currentEligible").GetBoolean());var version=detail.GetProperty("request").GetProperty("version").GetUInt32();var decision=new TechnicalDecisionWrite(version,"ReadyForPlacement",f.Next,"مراجعة فنية اصطناعية: الخطوة التالية تناقش مع الإدارة",Guid.NewGuid());
        Assert.Equal(HttpStatusCode.Forbidden,(await Send(coach,$"{Technical}/{id}/decision",decision)).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,$"{Technical}/{id}/decision",decision with{Version=version+1})).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await Send(owner,$"{Technical}/{id}/decision",decision with{RecommendedLevelId=f.Level})).StatusCode);
        Assert.Equal(HttpStatusCode.OK,(await Send(owner,$"{Technical}/{id}/decision",decision)).StatusCode);Assert.Equal(HttpStatusCode.OK,(await Send(owner,$"{Technical}/{id}/decision",decision)).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,$"{Technical}/{id}/decision",decision with{FamilyNote="تغيير نفس المفتاح"})).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,$"{Technical}/{id}/decision",decision with{RequestId=Guid.NewGuid()})).StatusCode);
        publicData=await family.GetFromJsonAsync<JsonElement>(familyPath);Assert.Equal("ReadyForPlacement",publicData.GetProperty("items")[0].GetProperty("decision").GetProperty("outcome").GetString());Assert.Equal(decision.FamilyNote,publicData.GetProperty("items")[0].GetProperty("decision").GetProperty("familyNote").GetString());Assert.False((await TechnicalView(coach,f.Plan)).GetProperty("canRequest").GetBoolean());
        var after=await db.SportEnrollments.AsNoTracking().SingleAsync(e=>e.Id==f.Enrollment);Assert.Equal(before.TrainingLevelId,after.TrainingLevelId);Assert.Equal(before.LevelReviewedAtUtc,after.LevelReviewedAtUtc);Assert.Equal(before.TrainingGroupId,after.TrainingGroupId);Assert.Equal(collections,await db.Collections.CountAsync());Assert.Equal(subscriptions,await db.SubscriptionPeriods.CountAsync());Assert.Equal(notices,await db.AcademyNotices.CountAsync());Assert.Equal(report,await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28"));
        var record=await db.PlayerTechnicalReviewRequests.SingleAsync(r=>r.Id==id);record.LevelName="تغيير التاريخ";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());db.ChangeTracker.Clear();var sql=await Assert.ThrowsAsync<Npgsql.PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"UPDATE \"PlayerTechnicalReviewRequests\" SET \"LevelName\"='overwrite' WHERE \"Id\"={id}"));Assert.Equal("23514",sql.SqlState);sql=await Assert.ThrowsAsync<Npgsql.PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM \"PlayerTechnicalReviewDecisions\" WHERE \"TechnicalRequestId\"={id}"));Assert.Equal("23514",sql.SqlState);
    }
    [Fact]public async Task Technical_review_preserves_request_evidence_when_later_observation_changes_and_requires_new_evidence_before_rerequest()
    {
        using var owner=await Staff();using var coach=await Mobile(AcademyRole.Coach);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var f=await TechnicalSetup(owner,coach,db);await MasterAll(coach,f);var body=TechnicalBody(await TechnicalView(coach,f.Plan));var response=await Send(coach,TechnicalPath(f.Plan),body);response.EnsureSuccessStatusCode();var id=(await response.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();
        (await Send(coach,$"{Skills}/plans/{f.Plan}/reviews",new SkillReviewWrite(f.Requirements[0],"Learning",null,f.Today,"تحديث أحدث: يحتاج تدريبًا",Guid.NewGuid()))).EnsureSuccessStatusCode();var detail=await owner.GetFromJsonAsync<JsonElement>($"{Technical}/{id}");Assert.True(detail.GetProperty("contextChanged").GetBoolean());Assert.All(detail.GetProperty("evidence").EnumerateArray(),v=>Assert.Equal("Mastered",v.GetProperty("state").GetString()));var version=detail.GetProperty("request").GetProperty("version").GetUInt32();Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,$"{Technical}/{id}/decision",new TechnicalDecisionWrite(version,"ReadyForPlacement",f.Next,null,Guid.NewGuid()))).StatusCode);
        (await Send(owner,$"{Technical}/{id}/decision",new TechnicalDecisionWrite(version,"ContextChanged",null,null,Guid.NewGuid()))).EnsureSuccessStatusCode();Assert.False((await TechnicalView(coach,f.Plan)).GetProperty("canRequest").GetBoolean());
        var original=await db.PlayerTechnicalReviewRequests.AsNoTracking().SingleAsync(r=>r.Id==id);var forged=new PlayerTechnicalReviewRequest{Id=Guid.NewGuid(),AcademyId=original.AcademyId,PlanId=original.PlanId,SportEnrollmentId=original.SportEnrollmentId,CurriculumId=original.CurriculumId,SportId=original.SportId,TrainingLevelId=original.TrainingLevelId,LevelName=original.LevelName,CurriculumTitle=original.CurriculumTitle,Sequence=2,PreviousRequestId=original.Id,SourceReviewSequence=original.SourceReviewSequence+1,EvidenceReviewIds=original.EvidenceReviewIds,ActorUserId=original.ActorUserId,ActorName=original.ActorName,RequestId=Guid.NewGuid(),RequestHash="forged-synthetic-proof"};db.PlayerTechnicalReviewRequests.Add(forged);var rejection=await Assert.ThrowsAsync<DbUpdateException>(()=>db.SaveChangesAsync());Assert.Equal("23514",Assert.IsType<Npgsql.PostgresException>(rejection.InnerException).SqlState);db.ChangeTracker.Clear();Assert.Equal(1,await db.PlayerTechnicalReviewRequests.CountAsync(r=>r.PlanId==f.Plan));
        await MasterAll(coach,f);var next=TechnicalBody(await TechnicalView(coach,f.Plan));Assert.Equal(id,next.PreviousRequestId);var second=await Send(coach,TechnicalPath(f.Plan),next);second.EnsureSuccessStatusCode();var secondId=(await second.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();detail=await owner.GetFromJsonAsync<JsonElement>($"{Technical}/{secondId}");version=detail.GetProperty("request").GetProperty("version").GetUInt32();
        (await Send(owner,$"{Technical}/{secondId}/decision",new TechnicalDecisionWrite(version,"NeedsPractice",null,null,Guid.NewGuid()))).EnsureSuccessStatusCode();Assert.False((await TechnicalView(coach,f.Plan)).GetProperty("canRequest").GetBoolean());Assert.Equal(2,await db.PlayerTechnicalReviewRequests.CountAsync(r=>r.PlanId==f.Plan));
        var assignment=await db.StaffGroupAssignments.SingleAsync(a=>a.TrainingGroupId==f.Group);assignment.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await coach.GetAsync(TechnicalPath(f.Plan))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(coach,TechnicalPath(f.Plan),body)).StatusCode);
    }
    [Fact]public async Task Technical_review_scoped_admin_needs_players_edit_not_merely_evaluation_read_and_revocation_blocks_replay()=>await DelegateFixture(async(owner,admin,db,group,member)=>{
        using var coach=await Mobile(AcademyRole.Coach);var f=await TechnicalSetup(owner,coach,db,group);await MasterAll(owner,f);var create=await Send(owner,TechnicalPath(f.Plan),TechnicalBody(await TechnicalView(owner,f.Plan)));create.EnsureSuccessStatusCode();var id=(await create.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();
        var names=new[]{"evaluations","players"};var grants=await db.StaffActionGrants.Where(g=>g.MembershipId==member&&names.Contains(g.Module)).ToListAsync();var saved=grants.ToDictionary(g=>g.Module,g=>JsonSerializer.Serialize(g));
        foreach(var name in names){var g=grants.SingleOrDefault(g=>g.Module==name);if(g==null){g=new(){Id=Guid.NewGuid(),AcademyId=group.AcademyId,MembershipId=member,Module=name};db.StaffActionGrants.Add(g);grants.Add(g);}g.Read=true;g.Add=false;g.Edit=false;g.Delete=false;g.IsActive=true;}
        try{
            await db.SaveChangesAsync();var detail=await admin.GetFromJsonAsync<JsonElement>($"{Technical}/{id}");Assert.False(detail.GetProperty("canDecide").GetBoolean());var body=new TechnicalDecisionWrite(detail.GetProperty("request").GetProperty("version").GetUInt32(),"NeedsPractice",null,"ملخص مراجعة اصطناعي",Guid.NewGuid());Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,$"{Technical}/{id}/decision",body)).StatusCode);
            var players=grants.Single(g=>g.Module=="players");players.Edit=true;await db.SaveChangesAsync();Assert.True((await admin.GetFromJsonAsync<JsonElement>($"{Technical}/{id}")).GetProperty("canDecide").GetBoolean());(await Send(admin,$"{Technical}/{id}/decision",body)).EnsureSuccessStatusCode();players.Edit=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,$"{Technical}/{id}/decision",body)).StatusCode);
            var evaluation=grants.Single(g=>g.Module=="evaluations");players.Edit=true;evaluation.Read=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,$"{Technical}/{id}/decision",body)).StatusCode);evaluation.Read=true;await db.SaveChangesAsync();var access=await db.MembershipBranchAccesses.SingleAsync(a=>a.MembershipId==member&&a.BranchId==group.BranchId);access.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync($"{Technical}/{id}")).StatusCode);Assert.Equal(1,await db.PlayerTechnicalReviewDecisions.CountAsync(d=>d.TechnicalRequestId==id));
        }finally{foreach(var g in grants){if(saved.TryGetValue(g.Module,out var text))db.Entry(g).CurrentValues.SetValues(JsonSerializer.Deserialize<StaffActionGrant>(text)!);else db.StaffActionGrants.Remove(g);}await db.SaveChangesAsync();}
    });
}
